<section class="conversation-layout <?= $conversation?'has-selected':'' ?>" data-conversation-app data-conversation-id="<?= (int)($conversation['id']??0) ?>" data-poll-url="<?= $conversation?e(base_url('admin/conversas/'.$conversation['id'].'/poll')):'' ?>" data-poll-interval="<?= (int)($this->config['conversations_realtime_interval_seconds']??10)*1000 ?>">
