        <?php foreach($result['items'] as $item): ?><a class="conversation-list-item <?= $conversation&&(int)$item['id']===(int)$conversation['id']?'active':'' ?>" href="<?= e(base_url('admin/conversas?id='.$item['id'])) ?>">
