            <span class="conversation-summary"><strong><?= e($item['nome_contato']?:$item['cliente_nome']?:$item['telefone_normalizado']) ?></strong><small><?= e($item['ultima_mensagem_preview']?:'Sem mensagem') ?></small><em><?= e($item['tags']??'') ?></em></span>
            <span class="conversation-meta"><time><?= e($item['ultima_mensagem_em']?date('d/m H:i',strtotime($item['ultima_mensagem_em'])):'') ?></time><?php if((int)$item['nao_lidas']>0): ?><b><?= (int)$item['nao_lidas'] ?></b><?php endif; ?><small><?= e(str_replace('_',' ',$item['status'])) ?></small></span>
        </a><?php endforeach; ?>
    </aside>
    <?php if($conversation): ?>
    <section class="conversation-thread">
