            <?php $day=''; foreach($messages as $message): $messageDay=date('Y-m-d',strtotime($message['recebida_em']?:$message['enviada_em']?:$message['created_at'])); if($messageDay!==$day):$day=$messageDay;?><div class="message-day"><?= e(date('d/m/Y',strtotime($day))) ?></div><?php endif; ?>
