                <?php if($message['media_path']||$message['media_id']): $mediaUrl=base_url('admin/conversas/midia/'.$message['id']); $isImage=$message['tipo']==='IMAGEM'||$message['tipo']==='STICKER'||str_starts_with((string)$message['media_mime'],'image/'); $isAudio=$message['tipo']==='AUDIO'||str_starts_with((string)$message['media_mime'],'audio/'); ?><?php if($isImage): ?><a href="<?= e($mediaUrl) ?>" target="_blank" rel="noopener"><img src="<?= e($mediaUrl) ?>" alt="Imagem recebida" loading="lazy"></a><?php elseif($isAudio): ?><audio controls preload="metadata" src="<?= e($mediaUrl) ?>">Seu navegador não suporta áudio.</audio><?php else: ?><a href="<?= e($mediaUrl) ?>" target="_blank" rel="noopener">Abrir <?= e($message['media_nome']?:'anexo') ?></a><?php endif; ?><?php endif; ?>
                <footer><?= e(date('H:i',strtotime($message['recebida_em']?:$message['enviada_em']?:$message['created_at']))) ?><?php if($message['direcao']==='SAIDA'): ?> · <?= e($message['status']) ?><?php endif; ?><?php if($message['usuario_nome']): ?> · <?= e($message['usuario_nome']) ?><?php endif; ?></footer>
                <?php if($message['erro']): ?><span class="message-error"><?= e($message['erro']) ?></span><?php if(can('conversas.reply')&&in_array($message['tipo'],['TEXTO','TEMPLATE'],true)):?><form action="<?= e(base_url('admin/conversas/'.$conversation['id'].'/reenviar')) ?>" method="post"><?= csrf_field() ?><input type="hidden" name="mensagem_id" value="<?= (int)$message['id'] ?>"><button class="admin-secondary" type="submit">Tentar novamente</button></form><?php endif;?><?php endif; ?>
                <button class="message-reply" type="button" data-reply-message="<?= (int)$message['id'] ?>">Responder</button>
            </article><?php endforeach; ?>
        </div>
        <?php if(can('conversas.reply')): ?><div class="conversation-composer">
