        </div><?php endif; ?>
    </section>
    <aside class="conversation-contact">
        <section><p class="eyebrow">Contato</p><h2><?= e($conversation['cliente_nome']?:$conversation['lead_nome']?:'Novo contato') ?></h2><dl><dt>Telefone</dt><dd><?= e($conversation['telefone_normalizado']) ?></dd><dt>Origem</dt><dd><?= e($conversation['origem']?:'—') ?></dd><dt>Campanha</dt><dd><?= e($conversation['utm_campaign']?:'—') ?></dd><dt>Reserva</dt><dd><?= $conversation['reserva_id']?'<a href="'.e(base_url('admin/reservas/'.$conversation['reserva_id'])).'">'.e($conversation['reserva_codigo']).'</a>':'—' ?></dd></dl></section>
        <?php if(can('conversas.manage')): ?><form action="<?= e(base_url('admin/conversas/'.$conversation['id'].'/atualizar')) ?>" method="post" class="admin-form compact"><?= csrf_field() ?>
            <label>Status<select name="status"><?php foreach(['NOVA','EM_ATENDIMENTO','AGUARDANDO_CLIENTE','AGUARDANDO_EQUIPE','CONVERTIDA','FINALIZADA','ARQUIVADA','SPAM'] as $value): ?><option <?= $conversation['status']===$value?'selected':'' ?>><?= e($value) ?></option><?php endforeach; ?></select></label>
            <label>Prioridade<select name="prioridade"><?php foreach(['BAIXA','NORMAL','ALTA','URGENTE'] as $value): ?><option <?= $conversation['prioridade']===$value?'selected':'' ?>><?= e($value) ?></option><?php endforeach; ?></select></label>
            <label>Atendente<select name="atendente_id"><option value="">Não atribuído</option><?php foreach($agents as $agent): ?><option value="<?= (int)$agent['id'] ?>" <?= (int)$conversation['atendente_id']===(int)$agent['id']?'selected':'' ?>><?= e($agent['nome']) ?></option><?php endforeach; ?></select></label>
            <label>Cliente ID<input type="number" name="cliente_id" min="1" value="<?= e($conversation['cliente_id']??'') ?>"></label><label>Reserva ID<input type="number" name="reserva_id" min="1" value="<?= e($conversation['reserva_id']??'') ?>"></label>
            <fieldset><legend>Tags</legend><?php foreach($tags as $tag): ?><label class="check-row"><input type="checkbox" name="tags[]" value="<?= (int)$tag['id'] ?>" <?= in_array((int)$tag['id'],$assignedTags,true)?'checked':'' ?>><span style="--tag-color:<?= e($tag['cor']) ?>"><?= e($tag['nome']) ?></span></label><?php endforeach; ?></fieldset>
            <button class="admin-primary">Salvar atendimento</button>
        </form><?php endif; ?>
        <details><summary>Notas internas</summary><?php if(can('conversas.manage')): ?><form action="<?= e(base_url('admin/conversas/'.$conversation['id'].'/nota')) ?>" method="post" class="admin-form"><?= csrf_field() ?><textarea name="nota" maxlength="2000" required></textarea><button class="admin-secondary">Adicionar nota</button></form><?php endif; ?><?php foreach($notes as $note): ?><article class="internal-note"><p><?= nl2br(e($note['texto'])) ?></p><small><?= e($note['usuario_nome']?:'Sistema') ?> · <?= e(date('d/m/Y H:i',strtotime($note['created_at']))) ?></small></article><?php endforeach; ?></details>
        <?php if(can('reservas.create')): ?><details><summary>Criar solicitação de reserva</summary><form action="<?= e(base_url('admin/conversas/'.$conversation['id'].'/criar-reserva')) ?>" method="post" class="admin-form compact"><?= csrf_field() ?><input name="nome" value="<?= e($conversation['nome_contato']?:$conversation['cliente_nome']?:'') ?>" placeholder="Nome" required><input type="email" name="email" value="<?= e($conversation['cliente_email']??'') ?>" placeholder="E-mail" required><label>Check-in<input type="date" name="checkin" min="<?= date('Y-m-d') ?>" required></label><label>Check-out<input type="date" name="checkout" min="<?= date('Y-m-d',strtotime('+1 day')) ?>" required></label><input type="number" name="adultos" min="1" value="1" required><input type="number" name="criancas" min="0" value="0" required><textarea name="observacoes" placeholder="Observações"></textarea><button class="admin-primary">Criar solicitação</button></form></details><?php endif; ?>
